CREATE TABLE IF NOT EXISTS articles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), original_title TEXT NOT NULL, source_name TEXT NOT NULL, source_url TEXT, published_at TIMESTAMPTZ, category TEXT NOT NULL, subcategory TEXT NOT NULL, language TEXT NOT NULL, summary TEXT, key_facts JSONB NOT NULL DEFAULT '[]', business_perspective TEXT, business_signal TEXT, product_innovation_perspective TEXT, innovation_signal TEXT, priority_score NUMERIC(5,2), priority_level TEXT, duplicate_group TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS article_status (article_id UUID PRIMARY KEY REFERENCES articles(id) ON DELETE CASCADE, read BOOLEAN NOT NULL DEFAULT false, bookmarked BOOLEAN NOT NULL DEFAULT false, archived BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_name TEXT UNIQUE NOT NULL, source_type TEXT NOT NULL, source_url TEXT, rss_url TEXT, active BOOLEAN NOT NULL DEFAULT true, last_successful_fetch TIMESTAMPTZ, last_error TEXT);
CREATE INDEX IF NOT EXISTS articles_published_idx ON articles(published_at DESC); CREATE INDEX IF NOT EXISTS articles_search_idx ON articles USING GIN (to_tsvector('simple', coalesce(original_title,'')||' '||coalesce(summary,'')));
